#include <stdio.h>
/* ex04：停等 / GBN 的信道利用率
 * 设帧发送时延 Td，往返时延 RTT，忽略 ACK 发送时间与处理时间：
 *   停等：每发 1 帧等 1 个 RTT -> U = Td / (Td + RTT)
 *   GBN ：窗口 W，可连续发 W 帧再等 ACK -> U = min(1, W*Td / (Td + RTT))
 * 关键：当 W*Td >= Td+RTT（即 W >= 1 + RTT/Td）时，信道被"填满"，U=1。
 * 注意：表头全部用 ASCII，是为了在等宽终端里严格对齐——中文是双宽字符，
 *      混在 printf 的 %-10s 里会错列，这是写这类报表工具时最常踩的坑。*/
int main(void) {
    double rate_mbps = 100.0;      /* 100 Mbps */
    int    frame_bit = 12000;      /* 1500 字节帧 */
    double rtt_ms[]  = {0.1, 2.0, 40.0};
    const char *nm[] = {"LAN(0.1ms)", "MAN(2ms)", "WAN(40ms)"};

    printf("帧长 %d bit，速率 %.0f Mbps\n", frame_bit, rate_mbps);
    printf("--------------------------------------------------------------\n");
    printf("%-12s %-9s %-9s %-9s %s\n", "link", "Td(ms)", "RTT(ms)", "U_stop", "W_need(帧)");

    for (int i = 0; i < 3; i++) {
        double td = frame_bit / (rate_mbps * 1e6) * 1000.0;     /* ms */
        double u_sw = td / (td + rtt_ms[i]);
        /* 需要的最小窗口：W*Td >= Td + RTT  =>  W >= 1 + RTT/Td */
        double w_need = 1.0 + rtt_ms[i] / td;
        printf("%-12s %-9.3f %-9.1f %-9.3f >= %.0f\n", nm[i], td, rtt_ms[i], u_sw, w_need);
    }
    printf("--------------------------------------------------------------\n");

    /* 放大看 GBN 在不同窗口下的利用率（跨省） */
    double td = frame_bit / (rate_mbps * 1e6) * 1000.0;
    double rtt = 40.0;
    double w_need = 1.0 + rtt / td;
    printf("\n跨省链路（Td=%.3fms, RTT=%.0fms）下 GBN 的利用率随窗口变化：\n", td, rtt);
    printf("（要填满信道需要 W >= %.0f 帧）\n\n", w_need);
    printf("%-10s %-9s %s\n", "W(frames)", "U", "verdict");
    int ws[] = {1, 2, 8, 32, 128, 334, 512};
    for (int i = 0; i < 7; i++) {
        double u = (ws[i] * td) / (td + rtt);
        if (u > 1.0) u = 1.0;
        printf("%-10d %-9.3f %s\n", ws[i], u,
               u >= 0.999 ? "填满" : "空闲");
    }
    printf("\n结论：\n");
    printf("  1) 停等协议在长肥管道上效率极低（跨省只有 %.1f%%）；\n", 100 * td / (td + rtt));
    printf("  2) 加带宽反而让 Td 更小、停等效率更低 —— 所以必须用滑动窗口；\n");
    printf("  3) 窗口至少要 1 + RTT/Td 才能填满信道，这就是「带宽时延积」的另一种表述。\n");
    return 0;
}
